insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Promoção de migração ilegal: promover, por qualquer meio, com o fim de obter vantagem econômica, a entrada ilegal de estrangeiro em território nacional ou de brasileiro em país estrangeiro: reclusão de 2 a 5 anos e multa. Na mesma pena quem promove, com o fim de obter vantagem econômica, a saída de estrangeiro do território nacional para ingressar ilegalmente em país estrangeiro. A pena é aumentada de 1/6 a 1/3 se o crime é cometido com violência ou se a vítima é submetida a condição desumana ou degradante. A pena é aplicada sem prejuízo das infrações conexas.', '["Promover entrada ilegal para obter vantagem econômica.","Reclusão de 2 a 5 anos e multa.","Aumento de 1/6 a 1/3 com violência ou condição desumana.","Sem prejuízo das infrações conexas."]'::jsonb, '["Exige o FIM DE VANTAGEM ECONÔMICA.","Coiote: quem promove a travessia ilegal."]'::jsonb, 'O ''coiote'' que cobra para levar pessoas ilegalmente a outro país comete o crime.', '["Assertiva que dispensa a finalidade de vantagem econômica erra: ela integra o tipo."]'::jsonb, '[]'::jsonb, '["Lei de Tráfico de Pessoas"]'::jsonb, 'under_review', 'claude'
