insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É instituída a Lei Brasileira de Inclusão da Pessoa com Deficiência (Estatuto da Pessoa com Deficiência), destinada a assegurar e promover, em condições de igualdade, o exercício dos direitos e das liberdades fundamentais por pessoa com deficiência, visando à sua inclusão social e cidadania. A Lei tem como base a Convenção sobre os Direitos das Pessoas com Deficiência e seu Protocolo Facultativo, aprovados com status de emenda constitucional.', '["Lei Brasileira de Inclusão.","Igualdade, inclusão social e cidadania.","Base: Convenção sobre os Direitos das Pessoas com Deficiência."]'::jsonb, '["A Convenção foi aprovada pelo procedimento do art. 5º, §3º, da Constituição (equivalente a emenda constitucional)."]'::jsonb, 'A Lei aplica a Convenção internacional como base para as regras de inclusão.', '["Assertiva que trata a Convenção como mera norma infraconstitucional erra: foi aprovada com status de emenda constitucional."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Considera-se pessoa com deficiência aquela que tem impedimento de longo prazo de natureza física, mental, intelectual ou sensorial, o qual, em interação com uma ou mais barreiras, pode obstruir sua participação plena e efetiva na sociedade em igualdade de condições com as demais pessoas. A avaliação da deficiência, quando necessária, será biopsicossocial, realizada por equipe multiprofissional e interdisciplinar, considerando os impedimentos nas funções e estruturas do corpo, os fatores socioambientais, psicológicos e pessoais, a limitação no desempenho de atividades e a restrição de participação. O Poder Executivo criará instrumentos de avaliação, e o exame médico-pericial poderá ser feito por telemedicina ou análise documental.', '["Conceito: impedimento de longo prazo + barreiras.","Avaliação biopsicossocial por equipe multiprofissional.","Quatro critérios de avaliação.","Telemedicina ou análise documental no exame pericial."]'::jsonb, '["Modelo BIOPSICOSSOCIAL, e não apenas médico.","Impedimento de LONGO PRAZO."]'::jsonb, 'A perícia avalia o corpo, o ambiente, as atividades e a participação social da pessoa.', '["Assertiva que baseia a avaliação da deficiência exclusivamente em laudo médico erra: é biopsicossocial."]'::jsonb, '[{"termo":"Avaliação biopsicossocial","significado":"Análise que une aspectos biológicos, psicológicos e sociais."}]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É instituído o cordão de fita com desenhos de girassóis como símbolo nacional de identificação de pessoas com deficiências ocultas. O uso do símbolo é opcional, e sua ausência não prejudica o exercício de direitos. A utilização não dispensa a apresentação de documento comprobatório da deficiência, se solicitado pelo atendente ou autoridade competente.', '["Cordão de girassóis: símbolo das deficiências ocultas.","Uso opcional.","Não dispensa o documento comprobatório."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Uso OPCIONAL; ausência não prejudica direitos."]'::jsonb, 'A pessoa com autismo usa o cordão, mas pode ser solicitada a apresentar o laudo.', '["Assertiva que torna obrigatório o cordão de girassol para exercer direitos erra."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-2-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para os fins da Lei, consideram-se: acessibilidade (possibilidade e condição de alcance, com segurança e autonomia, de espaços, mobiliários, edificações, transportes, informação e comunicação e outros serviços, na zona urbana e rural); desenho universal (concepção de produtos, ambientes, programas e serviços utilizáveis por todos, sem necessidade de adaptação); tecnologia assistiva (produtos, recursos e serviços que promovam a funcionalidade e a autonomia); barreiras (qualquer entrave que limite a participação social, como urbanísticas, arquitetônicas, nos transportes, nas comunicações e atitudinais); entre outros conceitos.', '["Acessibilidade.","Desenho universal.","Tecnologia assistiva ou ajuda técnica.","Barreiras de vários tipos."]'::jsonb, '["Desenho universal dispensa adaptação posterior.","As barreiras incluem as ATITUDINAIS."]'::jsonb, 'Uma rampa projetada desde o início é desenho universal.', '["Assertiva que restringe as barreiras às arquitetônicas erra: há também as urbanísticas, de transporte, de comunicação e atitudinais."]'::jsonb, '[{"termo":"Tecnologia assistiva","significado":"Recursos que ampliam a autonomia da pessoa com deficiência."}]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Toda pessoa com deficiência tem direito à igualdade de oportunidades com as demais pessoas e não sofrerá nenhuma espécie de discriminação. Considera-se discriminação em razão da deficiência toda forma de distinção, restrição ou exclusão, por ação ou omissão, que tenha o propósito ou o efeito de prejudicar, impedir ou anular o reconhecimento ou o exercício dos direitos e liberdades fundamentais, incluindo a recusa de adaptações razoáveis e de fornecimento de tecnologias assistivas. A pessoa com deficiência não está obrigada à fruição de benefícios decorrentes de ação afirmativa.', '["Igualdade de oportunidades e vedação de discriminação.","Discriminação por ação ou omissão, com propósito ou efeito.","Recusa de adaptação razoável é discriminação.","Benefícios de ação afirmativa são opcionais."]'::jsonb, '["Recusar ADAPTAÇÃO RAZOÁVEL é discriminação.","Ação afirmativa não é obrigatória para a pessoa com deficiência."]'::jsonb, 'A empresa que se recusa a adaptar o posto de trabalho comete discriminação.', '["Assertiva que não considera discriminação a recusa de adaptações razoáveis erra."]'::jsonb, '[{"termo":"Adaptação razoável","significado":"Modificação necessária que não impõe ônus desproporcional."}]'::jsonb, '["Art. 88"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa com deficiência será protegida de toda forma de negligência, discriminação, exploração, violência, tortura, crueldade, opressão e tratamento desumano ou degradante. São considerados especialmente vulneráveis a criança, o adolescente, a mulher e o idoso, com deficiência.', '["Proteção contra negligência, discriminação, exploração, violência, tortura e crueldade.","Vulneráveis: criança, adolescente, mulher e idoso com deficiência."]'::jsonb, '["Quatro grupos especialmente vulneráveis."]'::jsonb, 'A mulher idosa com deficiência recebe proteção reforçada.', '["Assertiva que não considera especialmente vulnerável a mulher com deficiência erra."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-5'
