insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É dever de todos comunicar à autoridade competente qualquer forma de ameaça ou de violação aos direitos da pessoa com deficiência. Se, no exercício de suas funções, os juízes e tribunais tiverem conhecimento de fatos que caracterizem violações previstas na Lei, devem remeter peças ao Ministério Público.', '["Dever de todos de comunicar ameaças ou violações.","Juízes e tribunais enviam peças ao Ministério Público."]'::jsonb, '["O dever é de TODOS."]'::jsonb, 'O juiz que identifica violação envia peças ao Ministério Público.', '["Assertiva que isenta os juízes do dever de remeter peças ao MP erra."]'::jsonb, '[]'::jsonb, '["Art. 79"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É dever do Estado, da sociedade e da família assegurar à pessoa com deficiência, com prioridade, a efetivação dos direitos referentes à vida, saúde, sexualidade, paternidade e maternidade, alimentação, habitação, educação, profissionalização, trabalho, previdência social, habilitação e reabilitação, transporte, acessibilidade, cultura, desporto, turismo, lazer, informação, comunicação, avanços científicos e tecnológicos, dignidade, respeito, liberdade e convivência familiar e comunitária, entre outros.', '["Dever do Estado, da sociedade e da família.","Prioridade absoluta.","Rol amplo de direitos."]'::jsonb, '["Dever de TRÊS atores: Estado, sociedade e família."]'::jsonb, 'A família e o Estado devem garantir a educação inclusiva.', '["Assertiva que restringe o dever ao Estado erra."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa com deficiência tem direito a atendimento prioritário, sobretudo para proteção e socorro em quaisquer circunstâncias; atendimento em todas as instituições e serviços ao público; recursos humanos e tecnológicos que garantam igualdade de condições; pontos de parada, estações e terminais acessíveis e segurança no embarque e desembarque; acesso a informações e comunicação acessíveis; recebimento de restituição de imposto de renda; e tramitação processual prioritária em todos os atos. Os direitos são extensivos ao acompanhante ou atendente pessoal, exceto quanto à restituição do imposto de renda e à prioridade processual. Nos serviços de emergência, a prioridade é condicionada aos protocolos de atendimento médico.', '["Atendimento prioritário em instituições e serviços.","Prioridade na restituição do imposto de renda e na tramitação processual.","Extensivo ao acompanhante, exceto imposto de renda e prioridade processual.","Emergência: protocolos médicos."]'::jsonb, '["Acompanhante NÃO tem prioridade na restituição do IR nem na tramitação processual.","Na emergência, vale a gravidade clínica."]'::jsonb, 'O acompanhante também é atendido com prioridade no banco, mas não na restituição do imposto.', '["Assertiva que estende ao acompanhante a prioridade processual erra."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao poder público garantir a dignidade da pessoa com deficiência ao longo de toda a vida. Em situações de risco, emergência ou estado de calamidade pública, a pessoa com deficiência será considerada vulnerável, devendo o poder público adotar medidas para sua proteção e segurança.', '["Dignidade ao longo de toda a vida.","Vulnerabilidade em risco, emergência e calamidade."]'::jsonb, '["Proteção especial em calamidades."]'::jsonb, 'Em uma enchente, o poder público prioriza o resgate de pessoas com deficiência.', '["Assertiva que dispensa medidas específicas em calamidade pública erra."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-10'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa com deficiência não poderá ser obrigada a se submeter a intervenção clínica ou cirúrgica, a tratamento ou a institucionalização forçada. O consentimento da pessoa com deficiência em situação de curatela poderá ser suprido, na forma da lei.', '["Vedada intervenção, tratamento ou institucionalização forçada.","Consentimento do curatelado pode ser suprido."]'::jsonb, '["Vedada a institucionalização FORÇADA."]'::jsonb, 'A pessoa com deficiência não pode ser internada contra a vontade, salvo hipóteses legais.', '["Assertiva que autoriza a institucionalização forçada da pessoa com deficiência erra."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-11'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O consentimento prévio, livre e esclarecido da pessoa com deficiência é indispensável para a realização de tratamento, procedimento, hospitalização e pesquisa científica. Em caso de curatela, deve ser assegurada sua participação, no maior grau possível, para obtenção do consentimento. A pesquisa científica com pessoa em situação de tutela ou de curatela só pode ser realizada, em caráter excepcional, quando houver indícios de benefício direto para sua saúde ou de outras pessoas com deficiência e desde que não haja outra opção de eficácia comparável.', '["Consentimento prévio, livre e esclarecido.","Participação do curatelado.","Pesquisa com tutelados ou curatelados só excepcionalmente."]'::jsonb, '["Consentimento PRÉVIO, LIVRE e ESCLARECIDO."]'::jsonb, 'O hospital explica o procedimento à pessoa com deficiência antes de realizá-lo.', '["Assertiva que dispensa o consentimento da pessoa com deficiência para o tratamento erra."]'::jsonb, '[]'::jsonb, '["Art. 13"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-12'
