insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa com deficiência somente será atendida sem seu consentimento prévio, livre e esclarecido em casos de risco de morte e de emergência em saúde, resguardado seu superior interesse e adotadas as salvaguardas legais cabíveis.', '["Atendimento sem consentimento só em risco de morte ou emergência."]'::jsonb, '["Exceção restrita."]'::jsonb, 'Em parada cardíaca, o atendimento é feito sem o consentimento prévio.', '["Assertiva que permite tratar sem consentimento qualquer pessoa com deficiência, em qualquer situação, erra."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-13'
