insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'À pessoa com deficiência internada ou em observação é assegurado o direito a acompanhante ou a atendente pessoal, devendo o órgão ou a instituição de saúde proporcionar condições adequadas para sua permanência em tempo integral. Na impossibilidade, cabe ao profissional de saúde justificá-la por escrito, e a instituição deve adotar as providências para suprir a ausência.', '["Direito a acompanhante ou atendente pessoal.","Permanência em tempo integral.","Negativa justificada por escrito."]'::jsonb, '["Negativa só com justificativa ESCRITA."]'::jsonb, 'O hospital permite que o atendente pessoal fique com o paciente.', '["Assertiva que permite negar o acompanhante sem justificativa escrita erra."]'::jsonb, '[]'::jsonb, '["Art. 21"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-22'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São vedadas todas as formas de discriminação contra a pessoa com deficiência, inclusive por meio de cobrança de valores diferenciados por planos e seguros privados de saúde, em razão de sua condição.', '["Vedada a cobrança diferenciada pelos planos de saúde."]'::jsonb, '["Vedado cobrar mais por causa da deficiência."]'::jsonb, 'O plano não pode cobrar mensalidade maior por causa da deficiência.', '["Assertiva que permite cobrança maior pelo plano em razão da deficiência erra."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-23'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É assegurado à pessoa com deficiência o acesso aos serviços de saúde, públicos e privados, e às informações prestadas e recebidas, por meio de recursos de tecnologia assistiva e de todas as formas de comunicação. Os serviços públicos de saúde implementarão sistemas de comunicação aumentativa e alternativa de baixa tecnologia e promoverão a capacitação permanente das equipes para o atendimento de pessoas com necessidades complexas de comunicação.', '["Acesso à informação em saúde por tecnologia assistiva.","Comunicação aumentativa e alternativa.","Capacitação das equipes."]'::jsonb, '["ATUALIZAÇÃO: o parágrafo único foi incluído por lei posterior."]'::jsonb, 'A unidade de saúde usa pranchas de pictogramas para se comunicar com pacientes.', '["Assertiva que dispensa recursos de comunicação alternativa nos serviços públicos de saúde erra."]'::jsonb, '[]'::jsonb, '["Art. 62-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-24'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os espaços dos serviços de saúde, públicos e privados, devem assegurar o acesso da pessoa com deficiência, em conformidade com a legislação, mediante a remoção de barreiras, por meio de projetos arquitetônico, de ambientação de interior e de comunicação que atendam às especificidades das pessoas com deficiência física, sensorial, intelectual e mental.', '["Remoção de barreiras nos serviços de saúde.","Projetos arquitetônico, de interior e de comunicação."]'::jsonb, '["Vale para serviços públicos e privados."]'::jsonb, 'A clínica privada deve ter rampas e sinalização acessível.', '["Assertiva que restringe a acessibilidade aos serviços públicos de saúde erra."]'::jsonb, '[]'::jsonb, '["Art. 56"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-25'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os casos de suspeita ou de confirmação de violência contra a pessoa com deficiência serão objeto de notificação compulsória pelos serviços de saúde, públicos e privados, à autoridade policial e ao Ministério Público, além dos Conselhos dos Direitos da Pessoa com Deficiência. Considera-se violência qualquer ação ou omissão, em local público ou privado, que cause morte, dano ou sofrimento físico ou psicológico.', '["Notificação compulsória da suspeita ou confirmação de violência.","Polícia, Ministério Público e Conselhos.","Conceito amplo de violência."]'::jsonb, '["Basta a SUSPEITA para notificar."]'::jsonb, 'O hospital notifica a suspeita de maus-tratos à polícia e ao Ministério Público.', '["Assertiva que exige confirmação da violência para a notificação erra."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-26'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A educação constitui direito da pessoa com deficiência, assegurados sistema educacional inclusivo em todos os níveis e aprendizado ao longo de toda a vida, de forma a alcançar o máximo desenvolvimento possível de seus talentos e habilidades, segundo suas características, interesses e necessidades. É dever do Estado, da família, da comunidade escolar e da sociedade assegurar educação de qualidade, colocando-a a salvo de toda forma de violência, negligência e discriminação.', '["Educação como direito.","Sistema educacional inclusivo em todos os níveis.","Aprendizado ao longo da vida.","Dever do Estado, família, escola e sociedade."]'::jsonb, '["Educação INCLUSIVA em todos os níveis."]'::jsonb, 'A escola regular matricula e adapta o ensino ao aluno com deficiência.', '["Assertiva que restringe a educação inclusiva ao ensino fundamental erra: é em todos os níveis."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-27'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Incumbe ao poder público assegurar, criar, desenvolver, implementar, incentivar, acompanhar e avaliar sistema educacional inclusivo em todos os níveis e modalidades; aprimoramento dos sistemas educacionais para garantir acesso, permanência, participação e aprendizagem; projeto pedagógico que institucionalize o atendimento educacional especializado e adaptações razoáveis; oferta de educação bilíngue, em Libras como primeira língua e língua portuguesa escrita como segunda língua; medidas individualizadas e coletivas que maximizem o desenvolvimento acadêmico e social; e pesquisas sobre novos métodos e tecnologias, entre outras.', '["Sistema educacional inclusivo.","Atendimento educacional especializado.","Educação bilíngue: Libras como primeira língua.","Medidas individualizadas e coletivas."]'::jsonb, '["Libras como PRIMEIRA língua e português escrito como segunda."]'::jsonb, 'A escola bilíngue ensina o aluno surdo em Libras e português escrito.', '["Assertiva que coloca o português como primeira língua do surdo na educação bilíngue erra: é a Libras."]'::jsonb, '[{"termo":"Atendimento educacional especializado","significado":"Serviço complementar ao ensino regular para alunos com deficiência."}]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-28'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos processos seletivos para ingresso e permanência nos cursos de instituições de ensino superior e de educação profissional e tecnológica, públicas e privadas, devem ser adotadas medidas como atendimento preferencial; formulário de inscrição com campos para informar recursos de acessibilidade necessários; provas em formatos acessíveis; recursos de acessibilidade e tecnologia assistiva previamente solicitados; dilação de tempo, mediante solicitação e comprovação; critérios de avaliação que considerem a singularidade linguística da pessoa com deficiência, entre outras.', '["Atendimento preferencial.","Provas em formatos acessíveis.","Recursos de tecnologia assistiva.","Dilação de tempo.","Avaliação que considere a singularidade linguística."]'::jsonb, '["Dilação de tempo depende de solicitação e comprovação."]'::jsonb, 'O candidato com deficiência visual faz a prova em Braille e com tempo adicional.', '["Assertiva que dispensa a comprovação da necessidade de dilação de tempo erra."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-30'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa com deficiência tem direito à moradia digna, no seio da família natural ou substituta, com seu cônjuge ou companheiro ou desacompanhada, ou em moradia para a vida independente, ou, ainda, em residência inclusiva. O poder público adotará programas e ações para apoiar a criação e a manutenção da moradia para a vida independente. A proteção integral na residência inclusiva será prestada no âmbito do Suas à pessoa em situação de dependência que não disponha de condições de autossustentabilidade, com vínculos familiares fragilizados ou rompidos.', '["Moradia digna em várias modalidades.","Moradia para a vida independente.","Residência inclusiva no Suas."]'::jsonb, '["Residência inclusiva: pessoa em dependência com vínculos fragilizados."]'::jsonb, 'A pessoa com deficiência pode morar em residência inclusiva custeada pelo Suas.', '["Assertiva que obriga a pessoa com deficiência a morar com a família erra: ela pode viver desacompanhada ou em moradia independente."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-31'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos programas habitacionais, públicos ou subsidiados com recursos públicos, a pessoa com deficiência ou seu responsável goza de prioridade na aquisição de imóvel, observada a reserva de, no mínimo, 3% das unidades habitacionais; em edificação multifamiliar, a acessibilidade nas áreas comuns e nas unidades do térreo, com acessibilidade ou adaptação razoável nos demais pisos; equipamentos urbanos comunitários acessíveis; e especificações para instalação de elevadores. O direito à prioridade é reconhecido apenas uma vez. Os critérios de financiamento devem ser compatíveis com os rendimentos. Se não houver interessado, as unidades reservadas serão disponibilizadas às demais pessoas.', '["Reserva mínima de 3% das unidades.","Acessibilidade em áreas comuns e no térreo.","Prioridade reconhecida apenas uma vez.","Sobras vão para as demais pessoas."]'::jsonb, '["Reserva de no mínimo 3%.","Prioridade só UMA vez."]'::jsonb, 'Em um conjunto habitacional público, 3% das unidades são reservadas para pessoas com deficiência.', '["Assertiva que fixa em 10% a reserva de unidades erra: é de no mínimo 3%."]'::jsonb, '[]'::jsonb, '["Art. 33"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-32'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao poder público compete adotar as providências necessárias para o cumprimento dos arts. 31 e 32 e divulgar, para os agentes interessados e beneficiários, a política habitacional prevista nas legislações federal, estaduais, distrital e municipais, com ênfase nos dispositivos sobre acessibilidade.', '["Providências para cumprir os arts. 31 e 32.","Divulgação da política habitacional."]'::jsonb, '["Dever de divulgação."]'::jsonb, 'A prefeitura divulga como obter moradia acessível.', '["Assertiva que dispensa a divulgação da política habitacional erra."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-33'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa com deficiência tem direito ao trabalho de sua livre escolha e aceitação, em ambiente acessível e inclusivo, em igualdade de oportunidades. As pessoas jurídicas de direito público, privado ou de qualquer natureza são obrigadas a garantir ambientes de trabalho acessíveis e inclusivos. Há direito a condições justas e favoráveis, incluindo igual remuneração por trabalho de igual valor. É vedada restrição ao trabalho e qualquer discriminação, inclusive no recrutamento, seleção, contratação, exames admissional e periódico, permanência, ascensão profissional e reabilitação, bem como a exigência de aptidão plena. Há direito a cursos, treinamentos, planos de carreira, promoções e incentivos em igualdade, com acessibilidade nos cursos de formação.', '["Trabalho de livre escolha em ambiente acessível.","Igual remuneração por trabalho de igual valor.","Vedada a exigência de aptidão plena.","Direito a treinamentos, promoções e planos de carreira."]'::jsonb, '["Vedada a exigência de APTIDÃO PLENA."]'::jsonb, 'A empresa não pode exigir aptidão plena em exame admissional.', '["Assertiva que permite exigir aptidão plena da pessoa com deficiência erra: é vedado."]'::jsonb, '[]'::jsonb, '["Art. 35"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-34'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É finalidade primordial das políticas públicas de trabalho e emprego promover e garantir condições de acesso e de permanência da pessoa com deficiência no campo de trabalho. Os programas de estímulo ao empreendedorismo e ao trabalho autônomo, incluídos o cooperativismo e o associativismo, devem prever a participação da pessoa com deficiência e a disponibilização de linhas de crédito, quando necessárias.', '["Acesso e permanência no trabalho.","Empreendedorismo, cooperativismo e crédito."]'::jsonb, '["Finalidade primordial das políticas de trabalho."]'::jsonb, 'O programa de microcrédito inclui empreendedores com deficiência.', '["Assertiva que exclui o empreendedorismo das políticas de trabalho para a pessoa com deficiência erra."]'::jsonb, '[]'::jsonb, '["Art. 36"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-35'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público deve implementar serviços e programas completos de habilitação e reabilitação profissional para que a pessoa com deficiência possa ingressar, continuar ou retornar ao campo do trabalho, respeitados sua livre escolha, vocação e interesse. Equipe multidisciplinar indicará, com base nos critérios da avaliação biopsicossocial, o programa adequado. Habilitação profissional é o processo de aquisição de conhecimentos, habilidades e aptidões para o exercício de profissão. Os serviços devem ter recursos para atender a toda pessoa com deficiência, independentemente de sua característica específica.', '["Habilitação e reabilitação profissional.","Respeito à livre escolha, vocação e interesse.","Indicação por equipe multidisciplinar."]'::jsonb, '["Respeita a LIVRE ESCOLHA da pessoa."]'::jsonb, 'O programa de reabilitação profissional prepara o trabalhador para nova função.', '["Assertiva que impõe a profissão à pessoa com deficiência erra: respeita-se a livre escolha."]'::jsonb, '[]'::jsonb, '["Art. 37"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-36'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constitui modo de inclusão da pessoa com deficiência no trabalho a colocação competitiva, em igualdade de oportunidades, nos termos da legislação trabalhista e previdenciária, com regras de acessibilidade, tecnologia assistiva e adaptação razoável. Pode ocorrer por meio de trabalho com apoio, com prioridade ao atendimento de quem tem maior dificuldade de inserção, suportes individualizados, respeito ao perfil vocacional, aconselhamento aos empregadores, avaliações periódicas, articulação intersetorial e participação de organizações da sociedade civil.', '["Colocação competitiva.","Trabalho com apoio.","Suportes individualizados e aconselhamento ao empregador."]'::jsonb, '["Colocação COMPETITIVA, e não apenas protegida."]'::jsonb, 'O trabalhador com deficiência intelectual é contratado com apoio de um agente facilitador.', '["Assertiva que restringe a inclusão a oficinas protegidas erra: a colocação competitiva é o modo previsto."]'::jsonb, '[{"termo":"Trabalho com apoio","significado":"Emprego competitivo com suportes individualizados."}]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-37'
