insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A entidade contratada para a realização de processo seletivo público ou privado para cargo, função ou emprego está obrigada à observância da Lei e de outras normas de acessibilidade vigentes.', '["Banca de concurso e seleções privadas devem cumprir as normas de acessibilidade."]'::jsonb, '["Alcança a entidade CONTRATADA para o processo seletivo."]'::jsonb, 'A banca do concurso deve garantir provas acessíveis.', '["Assertiva que isenta a banca organizadora das normas de acessibilidade erra."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
