select u.id, u.content_sha256, 'A pessoa com deficiência segurada do Regime Geral de Previdência Social tem direito à aposentadoria nos termos da Lei Complementar nº 142, de 8 de maio de 2013.', '["Aposentadoria da pessoa com deficiência segurada do RGPS, conforme a LC nº 142."]'::jsonb, '["Regime próprio: Lei Complementar nº 142, de 2013."]'::jsonb, 'O segurado com deficiência pode se aposentar com regras diferenciadas.', '["Assertiva que aplica as regras comuns de aposentadoria à pessoa com deficiência sem diferenciação erra."]'::jsonb, '[]'::jsonb, '["Art. 40"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-41'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa com deficiência tem direito à cultura, ao esporte, ao turismo e ao lazer em igualdade de oportunidades, sendo-lhe garantido o acesso a bens culturais em formato acessível; a programas de televisão, cinema, teatro e atividades culturais e desportivas em formato acessível; e a monumentos e espaços culturais. É vedada a recusa de oferta de obra intelectual em formato acessível, sob qualquer argumento, inclusive a proteção da propriedade intelectual. O poder público deve eliminar barreiras ao patrimônio cultural, observadas as normas de proteção, e incentivará museus e exposições a empregar comunicação aumentativa e alternativa.', '["Acesso à cultura, esporte, turismo e lazer.","Formato acessível.","Vedada a recusa de obra em formato acessível, mesmo por direito autoral."]'::jsonb, '["Direito autoral NÃO justifica a recusa de formato acessível."]'::jsonb, 'A editora não pode recusar a versão acessível de um livro alegando direito autoral.', '["Assertiva que admite a recusa de formato acessível com base na propriedade intelectual erra."]'::jsonb, '[]'::jsonb, '["Art. 43"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-42'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público deve promover a participação da pessoa com deficiência em atividades artísticas, intelectuais, culturais, esportivas e recreativas, com vistas ao seu protagonismo, incentivando a provisão de instrução, treinamento e recursos adequados; assegurando acessibilidade nos locais de eventos e nos serviços; e assegurando a participação em jogos e atividades recreativas, esportivas, de lazer, culturais e artísticas, inclusive no sistema escolar.', '["Participação em atividades artísticas, esportivas e culturais.","Acessibilidade nos locais de eventos.","Participação no sistema escolar."]'::jsonb, '["Foco no PROTAGONISMO."]'::jsonb, 'A escola inclui o aluno com deficiência nas atividades esportivas.', '["Assertiva que restringe o direito ao esporte ao nível competitivo erra."]'::jsonb, '[]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-43'
