insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As locadoras de veículos são obrigadas a oferecer 1 veículo adaptado para uso de pessoa com deficiência, a cada conjunto de 20 veículos de sua frota. O veículo adaptado deverá ter, no mínimo, câmbio automático, direção hidráulica, vidros elétricos e comandos manuais de freio e de embreagem.', '["1 veículo adaptado a cada 20 da frota.","Câmbio automático, direção hidráulica, vidros elétricos e comandos manuais."]'::jsonb, '["Proporção de 1 para 20."]'::jsonb, 'A locadora com 40 carros mantém 2 veículos adaptados.', '["Assertiva que fixa 1 veículo adaptado para cada 100 da frota erra: é 1 para cada 20."]'::jsonb, '[]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-52'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A acessibilidade é direito que garante à pessoa com deficiência ou com mobilidade reduzida viver de forma independente e exercer seus direitos de cidadania e de participação social.', '["Acessibilidade como direito instrumental da vida independente."]'::jsonb, '["Direito que viabiliza outros direitos."]'::jsonb, 'A rampa permite que a pessoa exerça sua cidadania.', '["Assertiva que trata a acessibilidade como mera recomendação erra: é direito."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-53'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sujeitam-se ao cumprimento da Lei e das normas de acessibilidade, sempre que houver interação com a matéria: a aprovação de projeto arquitetônico e urbanístico ou de comunicação e informação, a fabricação de veículos de transporte coletivo, a prestação do serviço e a execução de qualquer obra de destinação pública ou coletiva; a outorga ou renovação de concessão, permissão, autorização ou habilitação; a aprovação de financiamento de projeto com recursos públicos, por renúncia ou incentivo fiscal, contrato ou convênio; e a concessão de aval da União para empréstimo e financiamento internacionais.', '["Aprovação de projetos e obras de destinação coletiva.","Concessões e permissões.","Financiamento com recursos públicos.","Aval da União para empréstimos internacionais."]'::jsonb, '["Acessibilidade é condição para concessões, financiamentos e avais."]'::jsonb, 'O financiamento público de uma obra exige o cumprimento das regras de acessibilidade.', '["Assertiva que dispensa a acessibilidade nas obras financiadas com recursos públicos erra."]'::jsonb, '[]'::jsonb, '["Art. 64"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-54'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A concepção e a implantação de projetos que tratem do meio físico, de transporte, de informação e comunicação e de outros serviços abertos ao público devem atender aos princípios do desenho universal, tendo como referência as normas de acessibilidade. O desenho universal será sempre a regra geral. Se comprovadamente não puder ser empreendido, deve ser adotada adaptação razoável. O poder público promoverá a inclusão do tema nas diretrizes curriculares e nos programas de pesquisa e considerará o desenho universal desde a concepção das políticas públicas.', '["Desenho universal como regra geral.","Adaptação razoável quando inviável.","Inclusão do tema nos currículos e pesquisas."]'::jsonb, '["Desenho universal é a REGRA; adaptação razoável é a exceção."]'::jsonb, 'A prefeitura projeta uma praça já com acessibilidade, em vez de adaptá-la depois.', '["Assertiva que torna a adaptação razoável a regra geral erra: a regra é o desenho universal."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-55'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A construção, reforma, ampliação ou mudança de uso de edificações abertas ao público, de uso público ou privadas de uso coletivo deverão ser executadas de modo a serem acessíveis. As entidades de fiscalização profissional devem exigir, ao anotarem a responsabilidade técnica, a declaração de atendimento às regras de acessibilidade. Para aprovação, licenciamento ou certificado de conclusão de obra, deve ser atestado o atendimento às regras. O poder público, após certificar a acessibilidade, determinará a colocação do símbolo internacional de acesso.', '["Edificações coletivas devem ser acessíveis.","Responsabilidade técnica com declaração de acessibilidade.","Licenciamento e habite-se condicionados.","Símbolo de acesso após certificação."]'::jsonb, '["O profissional declara a observância das regras de acessibilidade."]'::jsonb, 'O arquiteto declara o atendimento à acessibilidade ao registrar a responsabilidade técnica.', '["Assertiva que dispensa o atestado de acessibilidade para o certificado de conclusão de obra erra."]'::jsonb, '[]'::jsonb, '["Art. 57"]'::jsonb, 'under_review', 'claude'
