insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O projeto e a construção de edificação de uso privado multifamiliar devem atender aos preceitos de acessibilidade, na forma regulamentar. As construtoras e incorporadoras devem assegurar percentual mínimo de unidades internamente acessíveis. É vedada a cobrança de valores adicionais para a aquisição dessas unidades.', '["Prédios multifamiliares com acessibilidade.","Percentual mínimo de unidades acessíveis.","Vedada a cobrança adicional."]'::jsonb, '["Vedado cobrar a mais pela unidade acessível."]'::jsonb, 'A incorporadora não pode cobrar valor extra pela unidade internamente acessível.', '["Assertiva que permite cobrança adicional pela unidade acessível erra."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
