insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Orientam-se pelas regras de acessibilidade os planos diretores municipais, os planos de transporte e trânsito, os de mobilidade urbana e de preservação de sítios históricos; os códigos de obras e de postura, as leis de uso e ocupação do solo e do sistema viário; os estudos prévios de impacto de vizinhança; a fiscalização e a imposição de sanções; e a legislação de prevenção contra incêndio e pânico. A concessão e a renovação de alvará de funcionamento são condicionadas à observação e certificação das regras de acessibilidade, assim como a carta de habite-se emitida antes das exigências, quando renovada.', '["Planos diretores, códigos de obras e posturas.","Alvará de funcionamento condicionado à acessibilidade.","Habite-se condicionado à acessibilidade."]'::jsonb, '["Alvará e habite-se dependem de certificação de acessibilidade."]'::jsonb, 'O alvará de um restaurante só é renovado se a acessibilidade for certificada.', '["Assertiva que dispensa a acessibilidade para a concessão de alvará erra."]'::jsonb, '[]'::jsonb, '["Art. 56"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-60'
