insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A formulação, a implementação e a manutenção das ações de acessibilidade atenderão às premissas de eleição de prioridades, elaboração de cronograma e reserva de recursos para a implementação das ações; e de planejamento contínuo e articulado entre os setores envolvidos.', '["Prioridades, cronograma e recursos.","Planejamento contínuo e articulado."]'::jsonb, '["Planejamento com recursos reservados."]'::jsonb, 'O município define prioridades e cronograma para adaptar calçadas.', '["Assertiva que dispensa cronograma e reserva de recursos erra."]'::jsonb, '[]'::jsonb, '["Art. 60"]'::jsonb, 'under_review', 'claude'
